import json
from pathlib import Path
from shapely.geometry import shape,Point,box,mapping
from shapely.ops import unary_union,polygonize
P=Path(__file__).parent
ways=[f for f in json.load(open(P/'source-ways.geojson'))['features'] if f['geometry']['type']=='LineString']
specs=[dict(name='Géfin Lakópark',slug='gefin-lakopark',point=[16.6092432,47.2273048],node=5696692619,roads=['Gagarin út','Géfin Gyula utca','Kálvária utca','Szent László király utca'],sourceUrl='https://kbr.szombathely.hu/kbrfile/55465.pdf',supportingUrls=['https://www.openstreetmap.org/node/5696692619','https://szombathely.hu/downloads/472/','https://utcak-magyarorszag.openalfa.com/utcak/szent-laszlo-kiraly-utca-gefin-lakopark-operint-szombathely'],approximationNote='Rough search area for the former barracks/Remix redevelopment block bounded by Gagarin út, Géfin Gyula utca, Kálvária utca and Szent László király utca. Municipal history supports the site and OSM supports the estate name within it. The complete historical block is used because individual development phases have no verified perimeter; northern nonresidential parts may be included.'),dict(name='Öntöde',slug='ontode',point=[16.6095069,47.2286067],node=5696692620,roads=['Gagarin út','Géfin Gyula utca','Esze Tamás utca','Szinyei Merse Pál utca'],sourceUrl='https://www.openstreetmap.org/node/5696692620',supportingUrls=['https://www.holahaz.hu/varos/szombathely/ontode','https://ontodesport.hu/kapcsolat/','https://utcak-magyarorszag.openalfa.com/utcak/fuerdo-utca-ontoede-operint-szombathely'],approximationNote='Estimated local street block containing the named Öntöde neighbourhood point, between Gagarin út, Géfin Gyula utca, Esze Tamás utca and Szinyei Merse Pál utca. The primary local landmark confirms Öntöde at Géfin Gyula utca 24. These are recognizable enclosing streets, not a verified administrative or development perimeter; the neighbourhood may extend beyond them.'),dict(name='Lovasiskola lakópark',slug='lovasiskola-lakopark',point=[16.5940921,47.2263873],node=8123953068,roads=['Jégpince út','Brenner János utca','Lovagló utca','Mélykúti út'],sourceUrl='https://www.openstreetmap.org/node/8123953068',supportingUrls=['https://www.holahaz.hu/varos/szombathely/lovasiskola-lakopark','https://utcak-magyarorszag.openalfa.com/utcak/jegpince-ut-koezephegy-szombathely','https://www.zsolt-lak.hu/index.php?kod=3024&modul=ingatlanok'],approximationNote='Estimated estate envelope between Jégpince út, Brenner János utca, Lovagló utca and Mélykúti út, enclosing Rákosi Jenő and Matók Leó streets and the named estate point. Local text identifies those central streets and describes adjacent garden land around Brenner/Lovagló. The road envelope includes the neighbouring riding ground and some gardens; individual parcel edges and the full estate extent remain uncertain.')]
for s in specs:
 fs=[f for f in ways if f['properties']['name'] in s['roads'] and shape(f['geometry']).intersects(box(16.58,47.215,16.62,47.235))]
 polygons=list(polygonize(unary_union([shape(f['geometry']) for f in fs])))
 candidates=[poly for poly in polygons if poly.covers(Point(s['point']))]
 print(s['name'],len(fs),'source lines',len(polygons),'enclosed polygons',len(candidates),'containing label')
 if not candidates:raise ValueError(s['name'])
 poly=min(candidates,key=lambda p:p.area)
 s['coordinates']=mapping(poly)['coordinates'][0]
 s['sourceWayIds']=[f['properties']['source']['osmId'] for f in fs if shape(f['geometry']).intersection(poly.boundary).length>1e-9]
 s['method']='Estimated source-defined street-block envelope: polygonize the archived real OSM geometry of '+', '.join(s['roads'])+' and select the closed block containing the archived named neighbourhood node. The point selects a block; it is not buffered.'
(P/'estate-traces.json').write_text(json.dumps(dict(units=specs),ensure_ascii=False,indent=2)+'\n')
